import { NextResponse } from "next/server";
import mongoose from "mongoose";

import { auth } from "@/auth";
import connectDB from "@/lib/mongodb";

import RestaurantOrder from "@/models/RestaurantOrder";
import MenuItem from "@/models/MenuItem";
import Booking from "@/models/booking";
import Cottage from "@/models/Cottage";

export const dynamic = "force-dynamic";

const roundMoney = (value) =>
  Math.round((Number(value) + Number.EPSILON) * 100) / 100;

async function verifyAdmin() {
  const session = await auth();

  if (session?.user?.role !== "admin") {
    return null;
  }

  return session;
}

// Validate a date and get its Bangladesh calendar-day boundaries.
function getDhakaDateRange(dateString) {
  if (
    typeof dateString !== "string" ||
    !/^\d{4}-\d{2}-\d{2}$/.test(dateString)
  ) {
    return null;
  }

  const [year, month, day] = dateString.split("-").map(Number);
  const checkDate = new Date(Date.UTC(year, month - 1, day));

  if (
    checkDate.getUTCFullYear() !== year ||
    checkDate.getUTCMonth() !== month - 1 ||
    checkDate.getUTCDate() !== day
  ) {
    return null;
  }

  const start = new Date(`${dateString}T00:00:00+06:00`);
  const end = new Date(start.getTime() + 24 * 60 * 60 * 1000);

  return { start, end };
}

// GET: Fetch restaurant orders
export async function GET() {
  try {
    const session = await verifyAdmin();

    if (!session) {
      return NextResponse.json(
        { success: false, message: "Unauthorized access." },
        { status: 403 }
      );
    }

    await connectDB();

    const orders = await RestaurantOrder.find()
      .sort({ createdAt: -1 })
      .limit(200)
      .populate("booking", "bookingReference guestName")
      .populate("cottage", "name")
      .populate("createdBy", "name")
      .lean();

    return NextResponse.json({
      success: true,
      orders,
    });
  } catch (error) {
    console.error("Restaurant orders GET error:", error);

    return NextResponse.json(
      { success: false, message: "Failed to load restaurant orders." },
      { status: 500 }
    );
  }
}

// POST: Create restaurant order
export async function POST(request) {
  try {
    const session = await verifyAdmin();

    if (!session) {
      return NextResponse.json(
        { success: false, message: "Unauthorized access." },
        { status: 403 }
      );
    }

    const adminId = session.user.id || session.user._id;

    if (!adminId || !mongoose.Types.ObjectId.isValid(adminId)) {
      return NextResponse.json(
        { success: false, message: "Invalid admin account." },
        { status: 400 }
      );
    }

    await connectDB();

    const body = await request.json();

    const {
      orderType,
      bookingId,
      selectedDate,
      items,
      extraCharges = [],
      discount = 0,
      paymentMode,
      guestName = "",
      guestPhone = "",
      note = "",
    } = body;

    // Validate order type
    if (!["walk-in", "cottage"].includes(orderType)) {
      return NextResponse.json(
        { success: false, message: "Invalid order type." },
        { status: 400 }
      );
    }

    // Validate payment mode
    if (!["pay_now", "cottage_bill"].includes(paymentMode)) {
      return NextResponse.json(
        { success: false, message: "Invalid payment mode." },
        { status: 400 }
      );
    }

    if (orderType === "walk-in" && paymentMode !== "pay_now") {
      return NextResponse.json(
        {
          success: false,
          message: "Walk-in orders must use pay now.",
        },
        { status: 400 }
      );
    }

    if (orderType === "walk-in" && !guestName.trim()) {
      return NextResponse.json(
        {
          success: false,
          message: "Customer name is required for walk-in orders.",
        },
        { status: 400 }
      );
    }

    if (!Array.isArray(items) || items.length < 1 || items.length > 50) {
      return NextResponse.json(
        { success: false, message: "Add between 1 and 50 food items." },
        { status: 400 }
      );
    }

    if (!Array.isArray(extraCharges) || extraCharges.length > 20) {
      return NextResponse.json(
        { success: false, message: "Invalid additional charges." },
        { status: 400 }
      );
    }

    if (
      !Number.isFinite(Number(discount)) ||
      Number(discount) < 0 ||
      roundMoney(discount) !== Number(discount)
    ) {
      return NextResponse.json(
        { success: false, message: "Invalid discount amount." },
        { status: 400 }
      );
    }

    if (
      typeof guestName !== "string" ||
      guestName.length > 100 ||
      typeof guestPhone !== "string" ||
      guestPhone.length > 30 ||
      typeof note !== "string" ||
      note.length > 500
    ) {
      return NextResponse.json(
        { success: false, message: "Invalid customer or order details." },
        { status: 400 }
      );
    }

    // Separate website menu items and custom items
    const menuQuantities = new Map();
    const customItems = [];

    for (const item of items) {
      const itemType = item.itemType || "menu";
      const quantity = Number(item.quantity);

      if (
        !Number.isInteger(quantity) ||
        quantity < 1 ||
        quantity > 100
      ) {
        return NextResponse.json(
          { success: false, message: "Invalid food quantity." },
          { status: 400 }
        );
      }

      if (itemType === "menu") {
        if (
          !item.menuItemId ||
          !mongoose.Types.ObjectId.isValid(item.menuItemId)
        ) {
          return NextResponse.json(
            { success: false, message: "Invalid menu item." },
            { status: 400 }
          );
        }

        const id = String(item.menuItemId);

        menuQuantities.set(
          id,
          (menuQuantities.get(id) || 0) + quantity
        );
      } else if (itemType === "custom") {
        const name =
          typeof item.name === "string" ? item.name.trim() : "";
        const price = Number(item.price);

        if (
          !name ||
          name.length > 100 ||
          !Number.isFinite(price) ||
          price <= 0 ||
          roundMoney(price) !== price
        ) {
          return NextResponse.json(
            {
              success: false,
              message: "Invalid custom food name or price.",
            },
            { status: 400 }
          );
        }

        customItems.push({
          itemType: "custom",
          menuItem: null,
          name,
          price: roundMoney(price),
          quantity,
          lineTotal: roundMoney(price * quantity),
        });
      } else {
        return NextResponse.json(
          { success: false, message: "Invalid food item type." },
          { status: 400 }
        );
      }
    }

    const totalItemCount = menuQuantities.size + customItems.length;

    if (totalItemCount > 50) {
      return NextResponse.json(
        { success: false, message: "Too many food items." },
        { status: 400 }
      );
    }

    // Fetch actual menu prices from database
    const menuIds = [...menuQuantities.keys()];

    const menuDocuments = menuIds.length
      ? await MenuItem.find({
          _id: { $in: menuIds },
          isAvailable: true,
        }).select("name price")
      : [];

    if (menuDocuments.length !== menuIds.length) {
      return NextResponse.json(
        {
          success: false,
          message: "One or more menu items are unavailable.",
        },
        { status: 400 }
      );
    }

    const menuItems = menuDocuments.map((menuItem) => {
      const quantity = menuQuantities.get(String(menuItem._id));
      const price = roundMoney(menuItem.price);

      if (!Number.isFinite(price) || price < 0) {
        throw new Error("Invalid menu price in database.");
      }

      return {
        itemType: "menu",
        menuItem: menuItem._id,
        name: menuItem.name,
        price,
        quantity,
        lineTotal: roundMoney(price * quantity),
      };
    });

    const orderItems = [...menuItems, ...customItems];

    // Calculate food subtotal
    const subtotal = roundMoney(
      orderItems.reduce((sum, item) => sum + item.lineTotal, 0)
    );

    // Validate and calculate additional charges
    const safeExtraCharges = [];

    for (const charge of extraCharges) {
      const name =
        typeof charge.name === "string" ? charge.name.trim() : "";
      const amount = Number(charge.amount);

      if (
        !name ||
        name.length > 100 ||
        !Number.isFinite(amount) ||
        amount <= 0 ||
        roundMoney(amount) !== amount
      ) {
        return NextResponse.json(
          {
            success: false,
            message: "Invalid additional charge name or amount.",
          },
          { status: 400 }
        );
      }

      safeExtraCharges.push({
        name,
        amount: roundMoney(amount),
      });
    }

    const extraChargesTotal = roundMoney(
      safeExtraCharges.reduce((sum, charge) => sum + charge.amount, 0)
    );

    // Calculate final bill
    const safeDiscount = roundMoney(discount);
    const totalBeforeDiscount = roundMoney(
      subtotal + extraChargesTotal
    );

    if (safeDiscount > totalBeforeDiscount) {
      return NextResponse.json(
        {
          success: false,
          message: "Discount cannot exceed the bill amount.",
        },
        { status: 400 }
      );
    }

    const total = roundMoney(totalBeforeDiscount - safeDiscount);

    if (total <= 0) {
      return NextResponse.json(
        {
          success: false,
          message: "Order total must be greater than zero.",
        },
        { status: 400 }
      );
    }

    // Validate cottage guest booking against the selected Dhaka date
    let booking = null;
    let cottage = null;
    let finalGuestName = guestName.trim();
    let finalGuestPhone = guestPhone.trim();

    if (orderType === "cottage") {
      if (
        !bookingId ||
        !mongoose.Types.ObjectId.isValid(bookingId)
      ) {
        return NextResponse.json(
          { success: false, message: "Select a valid cottage booking." },
          { status: 400 }
        );
      }

      const dateRange = getDhakaDateRange(selectedDate);

      if (!dateRange) {
        return NextResponse.json(
          {
            success: false,
            message: "Select a valid guest date before creating the order.",
          },
          { status: 400 }
        );
      }

      booking = await Booking.findOne({
        _id: bookingId,
        status: "confirmed",
        checkIn: { $lt: dateRange.end },
        checkOut: { $gte: dateRange.start },
      }).select(
        "bookingReference guestName guestPhone cottage"
      );

      if (!booking) {
        return NextResponse.json(
          {
            success: false,
            message:
              "This guest does not have a confirmed booking for the selected date.",
          },
          { status: 400 }
        );
      }

      cottage = await Cottage.findById(booking.cottage).select("name");

      if (!cottage) {
        return NextResponse.json(
          { success: false, message: "Cottage not found." },
          { status: 404 }
        );
      }

      finalGuestName = booking.guestName || finalGuestName;
      finalGuestPhone = booking.guestPhone || finalGuestPhone;
    }

    // Create order
    const order = await RestaurantOrder.create({
      orderType,
      booking: booking?._id || null,
      cottage: cottage?._id || null,

      guestName: finalGuestName,
      guestPhone: finalGuestPhone,

      items: orderItems,

      subtotal,
      extraCharges: safeExtraCharges,
      extraChargesTotal,

      discount: safeDiscount,
      total,

      paymentMode,
      paymentStatus: "unpaid",
      orderStatus: "open",

      note: note.trim(),
      createdBy: adminId,
    });

    return NextResponse.json(
      {
        success: true,
        message: "Restaurant order created successfully.",
        order: {
          _id: order._id,
          orderNumber: order.orderNumber,
          subtotal: order.subtotal,
          extraChargesTotal: order.extraChargesTotal,
          discount: order.discount,
          total: order.total,
          paymentMode: order.paymentMode,
          paymentStatus: order.paymentStatus,
        },
      },
      { status: 201 }
    );
  } catch (error) {
    console.error("Restaurant order POST error:", error);

    return NextResponse.json(
      {
        success: false,
        message: "Failed to create restaurant order.",
      },
      { status: 500 }
    );
  }
}

import { notFound } from "next/navigation";

import connectDB from "@/lib/mongodb";
import RestaurantOrder from "@/models/RestaurantOrder";
import Booking from "@/models/booking";
import Cottage from "@/models/Cottage";
import MenuItem from "@/models/MenuItem";
import User from "@/models/User";

import RestaurantOrderDetails from "@/components/admin/RestaurantOrderDetails";

export const dynamic = "force-dynamic";

export default async function RestaurantOrderDetailsPage({ params }) {
  const { id } = await params;

  await connectDB();

  const order = await RestaurantOrder.findById(id)
    .populate("booking", "bookingReference guestName guestPhone checkIn checkOut totalPrice paymentAmount paymentStatus payments")
    .populate("cottage", "name")
    .populate("createdBy", "name")
    .populate("payments.recordedBy", "name")
    .lean();

  if (!order) {
    notFound();
  }

  const safeOrder = JSON.parse(JSON.stringify(order));

  return <RestaurantOrderDetails order={safeOrder} />;
}

function formatMoney(amount) {
  return `৳${Number(amount || 0).toLocaleString("en-BD")}`;
}

function formatDate(date) {
  if (!date) return "Not available";

  return new Date(date).toLocaleString("en-BD", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Asia/Dhaka",
  });
}

function StatusBadge({ value }) {
  const styles = {
    open: "bg-blue-50 text-blue-700",
    completed: "bg-green-50 text-green-700",
    cancelled: "bg-red-50 text-red-700",
    unpaid: "bg-red-50 text-red-700",
    partially_paid: "bg-amber-50 text-amber-700",
    paid: "bg-green-50 text-green-700",
  };

  return (
    <span
      className={`rounded-full px-3 py-1 text-xs font-semibold ${
        styles[value] || "bg-gray-100 text-gray-700"
      }`}
    >
      {(value || "unknown").replaceAll("_", " ")}
    </span>
  );
}

export default function RestaurantOrderDetails({ order }) {
  const directPayments = order.payments || [];
  const checkoutAllocations = order.checkoutPaymentAllocations || [];

  const directPaid = directPayments.reduce(
    (sum, payment) => sum + Number(payment.amount || 0),
    0
  );

  const checkoutPaid = checkoutAllocations.reduce(
    (sum, allocation) => sum + Number(allocation.amount || 0),
    0
  );

  const totalPaid = directPaid + checkoutPaid;
  const outstanding = Math.max(0, Number(order.total || 0) - totalPaid);

  const totalQuantity = (order.items || []).reduce(
    (sum, item) => sum + Number(item.quantity || 0),
    0
  );

  return (
    <div className="mx-auto max-w-6xl space-y-6 pb-10">
      {/* Header */}
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
        <div>
          <a
            href="/admin/restaurant/orders"
            className="mb-3 inline-flex text-sm font-medium text-[#426b55] hover:underline"
          >
            ← Back to Restaurant Orders
          </a>

          <h1 className="text-2xl font-bold text-[#173729]">
            Restaurant Order Details
          </h1>

          <p className="mt-1 text-sm text-gray-500">
            Order #{order.orderNumber}
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <StatusBadge value={order.orderStatus} />
          <StatusBadge value={order.paymentStatus} />
        </div>
      </div>

      {/* Payment summary */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <SummaryCard
          label="Order Total"
          value={formatMoney(order.total)}
        />

        <SummaryCard
          label="Direct Payments"
          value={formatMoney(directPaid)}
        />

        <SummaryCard
          label="Checkout Allocations"
          value={formatMoney(checkoutPaid)}
        />

        <SummaryCard
          label="Outstanding Balance"
          value={formatMoney(outstanding)}
        />
      </div>

      {/* Order information */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Order Information
        </h2>

        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          <InfoItem label="Order Number" value={order.orderNumber} />

          <InfoItem
            label="Order Type"
            value={order.orderType}
          />

          <InfoItem
            label="Payment Mode"
            value={
              order.paymentMode === "cottage_bill"
                ? "Add to Cottage Bill"
                : "Pay Immediately"
            }
          />

          <InfoItem
            label="Customer"
            value={order.guestName || "Walk-in Guest"}
          />

          <InfoItem
            label="Phone"
            value={order.guestPhone || "Not provided"}
          />

          <InfoItem
            label="Cottage"
            value={order.cottage?.name || "Walk-in"}
          />

          <InfoItem
            label="Booking Reference"
            value={order.booking?.bookingReference || "N/A"}
          />

          <InfoItem
            label="Created At"
            value={formatDate(order.createdAt)}
          />

          <InfoItem
            label="Total Quantity"
            value={totalQuantity}
          />
        </div>
      </section>

      {/* Food items */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Food Items
        </h2>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[550px] text-left text-sm">
            <thead className="border-b bg-gray-50 text-gray-600">
              <tr>
                <th className="px-4 py-3">Item</th>
                <th className="px-4 py-3">Price</th>
                <th className="px-4 py-3">Quantity</th>
                <th className="px-4 py-3 text-right">Total</th>
              </tr>
            </thead>

            <tbody className="divide-y">
              {(order.items || []).map((item, index) => (
                <tr key={item._id || index}>
                  <td className="px-4 py-4 font-medium text-gray-800">
                    {item.name}
                    {item.itemType === "custom" && (
                      <span className="ml-2 text-xs text-gray-400">
                        Custom
                      </span>
                    )}
                  </td>

                  <td className="px-4 py-4">
                    {formatMoney(item.price)}
                  </td>

                  <td className="px-4 py-4">
                    {item.quantity}
                  </td>

                  <td className="px-4 py-4 text-right font-semibold">
                    {formatMoney(item.lineTotal)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Bill breakdown */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Extra Charges & Discount
        </h2>

        <div className="space-y-3">
          <BillRow label="Food Subtotal" amount={order.subtotal} />

          {(order.extraCharges || []).map((charge, index) => (
            <BillRow
              key={charge._id || index}
              label={charge.name}
              amount={charge.amount}
            />
          ))}

          <BillRow
            label="Total Additional Charges"
            amount={order.extraChargesTotal}
          />

          <BillRow
            label="Discount"
            amount={order.discount}
            negative
          />

          <div className="border-t pt-4">
            <BillRow
              label="Final Order Total"
              amount={order.total}
              bold
            />
          </div>
        </div>

        {order.note && (
          <div className="mt-5 rounded-lg bg-gray-50 p-4">
            <p className="text-xs font-semibold uppercase text-gray-500">
              Order Note
            </p>
            <p className="mt-1 text-sm text-gray-700">
              {order.note}
            </p>
          </div>
        )}
      </section>

      {/* Payment history */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Payment History
        </h2>

        {directPayments.length === 0 &&
        checkoutAllocations.length === 0 ? (
          <p className="rounded-lg bg-gray-50 p-5 text-sm text-gray-500">
            No payments have been recorded for this order yet.
          </p>
        ) : (
          <div className="space-y-3">
            {directPayments.map((payment, index) => (
              <div
                key={payment._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold capitalize text-gray-800">
                    {payment.method}
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(payment.paidAt)}
                  </p>
                  {payment.reference && (
                    <p className="mt-1 text-xs text-gray-500">
                      Reference: {payment.reference}
                    </p>
                  )}
                  {payment.recordedBy?.name && (
                    <p className="text-xs text-gray-500">
                      Recorded by: {payment.recordedBy.name}
                    </p>
                  )}
                </div>

                <p className="font-bold text-green-700">
                  {formatMoney(payment.amount)}
                </p>
              </div>
            ))}

            {checkoutAllocations.map((allocation, index) => (
              <div
                key={allocation._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border border-amber-200 bg-amber-50 p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold text-gray-800">
                    Cottage Checkout Payment
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(allocation.allocatedAt)}
                  </p>
                  <p className="text-xs text-gray-500">
                    Allocated from an existing booking payment
                  </p>
                </div>

                <p className="font-bold text-green-700">
                  {formatMoney(allocation.amount)}
                </p>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Order status */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="text-lg font-bold text-[#173729]">
          Order Status
        </h2>

        <p className="mt-2 text-sm text-gray-500">
          Current status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {order.orderStatus}
          </span>
        </p>

        <p className="mt-1 text-sm text-gray-500">
          Payment status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {(order.paymentStatus || "").replaceAll("_", " ")}
          </span>
        </p>

        <p className="mt-3 text-sm text-gray-500">
          Payment recording and order status controls will be added in the
          next steps.
        </p>
      </section>
    </div>
  );
}

function SummaryCard({ label, value }) {
  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
      <p className="text-sm text-gray-500">{label}</p>
      <p className="mt-2 text-2xl font-bold text-[#234b3b]">
        {value}
      </p>
    </div>
  );
}

function InfoItem({ label, value }) {
  return (
    <div>
      <p className="text-xs font-medium uppercase tracking-wide text-gray-400">
        {label}
      </p>
      <p className="mt-1 break-words text-sm font-semibold text-gray-800">
        {value || "N/A"}
      </p>
    </div>
  );
}

function BillRow({ label, amount, negative = false, bold = false }) {
  return (
    <div
      className={`flex items-center justify-between gap-4 ${
        bold ? "text-lg font-bold text-[#173729]" : "text-sm text-gray-600"
      }`}
    >
      <span>{label}</span>
      <span className={negative ? "text-red-600" : ""}>
        {negative && Number(amount) > 0 ? "-" : ""}
        {formatMoney(amount)}
      </span>
    </div>
  );
}

import { NextResponse } from "next/server";
import mongoose from "mongoose";

import { auth } from "@/auth";
import connectDB from "@/lib/mongodb";
import RestaurantOrder from "@/models/RestaurantOrder";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const roundMoney = (value) =>
  Math.round((Number(value) + Number.EPSILON) * 100) / 100;

async function verifyAdmin() {
  const session = await auth();

  if (session?.user?.role !== "admin") {
    return null;
  }

  return session;
}

export async function POST(request, { params }) {
  let session;

  try {
    session = await verifyAdmin();

    if (!session) {
      return NextResponse.json(
        { success: false, message: "Unauthorized access." },
        { status: 403 }
      );
    }

    const adminId = session.user.id || session.user._id;

    if (!adminId || !mongoose.Types.ObjectId.isValid(adminId)) {
      return NextResponse.json(
        { success: false, message: "Invalid admin account." },
        { status: 400 }
      );
    }

    const { id } = await params;

    if (!mongoose.Types.ObjectId.isValid(id)) {
      return NextResponse.json(
        { success: false, message: "Invalid restaurant order ID." },
        { status: 400 }
      );
    }

    const body = await request.json();

    const amount = Number(body.amount);
    const method = body.method;

    const reference =
      typeof body.reference === "string"
        ? body.reference.trim()
        : "";

    const note =
      typeof body.note === "string"
        ? body.note.trim()
        : "";

    // Validate payment amount.
    if (
      !Number.isFinite(amount) ||
      amount <= 0 ||
      roundMoney(amount) !== amount
    ) {
      return NextResponse.json(
        { success: false, message: "Enter a valid payment amount." },
        { status: 400 }
      );
    }

    // Validate payment method.
    const allowedMethods = ["cash", "bkash", "nagad", "bank"];

    if (!allowedMethods.includes(method)) {
      return NextResponse.json(
        { success: false, message: "Invalid payment method." },
        { status: 400 }
      );
    }

    if (reference.length > 100 || note.length > 500) {
      return NextResponse.json(
        { success: false, message: "Reference or note is too long." },
        { status: 400 }
      );
    }

    await connectDB();

    const dbSession = await mongoose.startSession();

    let result = null;

    try {
      await dbSession.withTransaction(async () => {
        const order = await RestaurantOrder.findById(id).session(
          dbSession
        );

        if (!order) {
          result = {
            status: 404,
            body: {
              success: false,
              message: "Restaurant order not found.",
            },
          };
          return;
        }

        if (order.orderStatus === "cancelled") {
          result = {
            status: 400,
            body: {
              success: false,
              message: "Payments cannot be added to a cancelled order.",
            },
          };
          return;
        }

        // Calculate payments already received directly.
        const directPaid = roundMoney(
          order.payments.reduce(
            (sum, payment) => sum + Number(payment.amount || 0),
            0
          )
        );

        // These are existing booking payments allocated to this order.
        const checkoutPaid = roundMoney(
          order.checkoutPaymentAllocations.reduce(
            (sum, allocation) =>
              sum + Number(allocation.amount || 0),
            0
          )
        );

        const totalPaid = roundMoney(directPaid + checkoutPaid);
        const outstanding = roundMoney(
          Number(order.total) - totalPaid
        );

        if (outstanding <= 0) {
          result = {
            status: 400,
            body: {
              success: false,
              message: "This restaurant order is already fully paid.",
            },
          };
          return;
        }

        if (amount > outstanding) {
          result = {
            status: 400,
            body: {
              success: false,
              message: `Payment exceeds the outstanding balance of ৳${outstanding.toLocaleString("en-BD")}.`,
              outstanding,
            },
          };
          return;
        }

        // Record the actual payment received by the resort.
        order.payments.push({
          amount: roundMoney(amount),
          method,
          reference,
          note,
          paidAt: new Date(),
          recordedBy: adminId,
        });

        const newTotalPaid = roundMoney(totalPaid + amount);

        if (newTotalPaid >= Number(order.total)) {
          order.paymentStatus = "paid";
        } else if (newTotalPaid > 0) {
          order.paymentStatus = "partially_paid";
        } else {
          order.paymentStatus = "unpaid";
        }

        await order.save({ session: dbSession });

        result = {
          status: 200,
          body: {
            success: true,
            message: "Restaurant payment recorded successfully.",
            payment: order.payments[order.payments.length - 1],
            paymentSummary: {
              orderTotal: order.total,
              directPaid: roundMoney(directPaid + amount),
              checkoutPaid,
              totalPaid: newTotalPaid,
              outstanding: roundMoney(
                Number(order.total) - newTotalPaid
              ),
              paymentStatus: order.paymentStatus,
            },
          },
        };
      });
    } finally {
      await dbSession.endSession();
    }

    return NextResponse.json(result.body, {
      status: result.status,
    });
  } catch (error) {
    console.error("Restaurant payment POST error:", error);

    return NextResponse.json(
      {
        success: false,
        message: "Failed to record restaurant payment.",
      },
      { status: 500 }
    );
  }
}

function formatMoney(amount) {
  return `৳${Number(amount || 0).toLocaleString("en-BD")}`;
}

function formatDate(date) {
  if (!date) return "Not available";

  return new Date(date).toLocaleString("en-BD", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Asia/Dhaka",
  });
}

function StatusBadge({ value }) {
  const styles = {
    open: "bg-blue-50 text-blue-700",
    completed: "bg-green-50 text-green-700",
    cancelled: "bg-red-50 text-red-700",
    unpaid: "bg-red-50 text-red-700",
    partially_paid: "bg-amber-50 text-amber-700",
    paid: "bg-green-50 text-green-700",
  };

  return (
    <span
      className={`rounded-full px-3 py-1 text-xs font-semibold ${styles[value] || "bg-gray-100 text-gray-700"
        }`}
    >
      {(value || "unknown").replaceAll("_", " ")}
    </span>
  );
}

export default function RestaurantOrderDetails({ order }) {
  const directPayments = order.payments || [];
  const checkoutAllocations = order.checkoutPaymentAllocations || [];

  const directPaid = directPayments.reduce(
    (sum, payment) => sum + Number(payment.amount || 0),
    0
  );

  const checkoutPaid = checkoutAllocations.reduce(
    (sum, allocation) => sum + Number(allocation.amount || 0),
    0
  );

  const totalPaid = directPaid + checkoutPaid;
  const outstanding = Math.max(0, Number(order.total || 0) - totalPaid);

  const totalQuantity = (order.items || []).reduce(
    (sum, item) => sum + Number(item.quantity || 0),
    0
  );

  return (
    <div className="mx-auto max-w-6xl space-y-6 pb-10">
      {/* Header */}
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
        <div>
          <a
            href="/admin/restaurant/orders"
            className="mb-3 inline-flex text-sm font-medium text-[#426b55] hover:underline"
          >
            ← Back to Restaurant Orders
          </a>

          <h1 className="text-2xl font-bold text-[#173729]">
            Restaurant Order Details
          </h1>

          <p className="mt-1 text-sm text-gray-500">
            Order #{order.orderNumber}
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <StatusBadge value={order.orderStatus} />
          <StatusBadge value={order.paymentStatus} />
        </div>
      </div>

      {/* Payment summary */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <SummaryCard
          label="Order Total"
          value={formatMoney(order.total)}
        />

        <SummaryCard
          label="Direct Payments"
          value={formatMoney(directPaid)}
        />

        <SummaryCard
          label="Checkout Allocations"
          value={formatMoney(checkoutPaid)}
        />

        <SummaryCard
          label="Outstanding Balance"
          value={formatMoney(outstanding)}
        />
      </div>

      {/* Order information */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Order Information
        </h2>

        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          <InfoItem label="Order Number" value={order.orderNumber} />

          <InfoItem
            label="Order Type"
            value={order.orderType}
          />

          <InfoItem
            label="Payment Mode"
            value={
              order.paymentMode === "cottage_bill"
                ? "Add to Cottage Bill"
                : "Pay Immediately"
            }
          />

          <InfoItem
            label="Customer"
            value={order.guestName || "Walk-in Guest"}
          />

          <InfoItem
            label="Phone"
            value={order.guestPhone || "Not provided"}
          />

          <InfoItem
            label="Cottage"
            value={order.cottage?.name || "Walk-in"}
          />

          <InfoItem
            label="Booking Reference"
            value={order.booking?.bookingReference || "N/A"}
          />

          <InfoItem
            label="Created At"
            value={formatDate(order.createdAt)}
          />

          <InfoItem
            label="Total Quantity"
            value={totalQuantity}
          />
        </div>
      </section>

      {/* Food items */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Food Items
        </h2>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[550px] text-left text-sm">
            <thead className="border-b bg-gray-50 text-gray-600">
              <tr>
                <th className="px-4 py-3">Item</th>
                <th className="px-4 py-3">Price</th>
                <th className="px-4 py-3">Quantity</th>
                <th className="px-4 py-3 text-right">Total</th>
              </tr>
            </thead>

            <tbody className="divide-y">
              {(order.items || []).map((item, index) => (
                <tr key={item._id || index}>
                  <td className="px-4 py-4 font-medium text-gray-800">
                    {item.name}
                    {item.itemType === "custom" && (
                      <span className="ml-2 text-xs text-gray-400">
                        Custom
                      </span>
                    )}
                  </td>

                  <td className="px-4 py-4">
                    {formatMoney(item.price)}
                  </td>

                  <td className="px-4 py-4">
                    {item.quantity}
                  </td>

                  <td className="px-4 py-4 text-right font-semibold">
                    {formatMoney(item.lineTotal)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Bill breakdown */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Extra Charges & Discount
        </h2>

        <div className="space-y-3">
          <BillRow label="Food Subtotal" amount={order.subtotal} />

          {(order.extraCharges || []).map((charge, index) => (
            <BillRow
              key={charge._id || index}
              label={charge.name}
              amount={charge.amount}
            />
          ))}

          <BillRow
            label="Total Additional Charges"
            amount={order.extraChargesTotal}
          />

          <BillRow
            label="Discount"
            amount={order.discount}
            negative
          />

          <div className="border-t pt-4">
            <BillRow
              label="Final Order Total"
              amount={order.total}
              bold
            />
          </div>
        </div>

        {order.note && (
          <div className="mt-5 rounded-lg bg-gray-50 p-4">
            <p className="text-xs font-semibold uppercase text-gray-500">
              Order Note
            </p>
            <p className="mt-1 text-sm text-gray-700">
              {order.note}
            </p>
          </div>
        )}
      </section>

      {/* Payment history */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Payment History
        </h2>

        {directPayments.length === 0 &&
          checkoutAllocations.length === 0 ? (
          <p className="rounded-lg bg-gray-50 p-5 text-sm text-gray-500">
            No payments have been recorded for this order yet.
          </p>
        ) : (
          <div className="space-y-3">
            {directPayments.map((payment, index) => (
              <div
                key={payment._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold capitalize text-gray-800">
                    {payment.method}
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(payment.paidAt)}
                  </p>
                  {payment.reference && (
                    <p className="mt-1 text-xs text-gray-500">
                      Reference: {payment.reference}
                    </p>
                  )}
                  {payment.recordedBy?.name && (
                    <p className="text-xs text-gray-500">
                      Recorded by: {payment.recordedBy.name}
                    </p>
                  )}
                </div>

                <p className="font-bold text-green-700">
                  {formatMoney(payment.amount)}
                </p>
              </div>
            ))}

            {checkoutAllocations.map((allocation, index) => (
              <div
                key={allocation._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border border-amber-200 bg-amber-50 p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold text-gray-800">
                    Cottage Checkout Payment
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(allocation.allocatedAt)}
                  </p>
                  <p className="text-xs text-gray-500">
                    Allocated from an existing booking payment
                  </p>
                </div>

                <p className="font-bold text-green-700">
                  {formatMoney(allocation.amount)}
                </p>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Order status */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="text-lg font-bold text-[#173729]">
          Order Status
        </h2>

        <p className="mt-2 text-sm text-gray-500">
          Current status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {order.orderStatus}
          </span>
        </p>

        <p className="mt-1 text-sm text-gray-500">
          Payment status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {(order.paymentStatus || "").replaceAll("_", " ")}
          </span>
        </p>

        <p className="mt-3 text-sm text-gray-500">
          Payment recording and order status controls will be added in the
          next steps.
        </p>
      </section>
    </div>
  );
}

function SummaryCard({ label, value }) {
  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
      <p className="text-sm text-gray-500">{label}</p>
      <p className="mt-2 text-2xl font-bold text-[#234b3b]">
        {value}
      </p>
    </div>
  );
}

function InfoItem({ label, value }) {
  return (
    <div>
      <p className="text-xs font-medium uppercase tracking-wide text-gray-400">
        {label}
      </p>
      <p className="mt-1 break-words text-sm font-semibold text-gray-800">
        {value || "N/A"}
      </p>
    </div>
  );
}

function BillRow({ label, amount, negative = false, bold = false }) {
  return (
    <div
      className={`flex items-center justify-between gap-4 ${bold ? "text-lg font-bold text-[#173729]" : "text-sm text-gray-600"
        }`}
    >
      <span>{label}</span>
      <span className={negative ? "text-red-600" : ""}>
        {negative && Number(amount) > 0 ? "-" : ""}
        {formatMoney(amount)}
      </span>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

function formatMoney(amount) {
  return `৳${Number(amount || 0).toLocaleString("en-BD")}`;
}

function formatDate(date) {
  if (!date) return "Not available";

  return new Date(date).toLocaleString("en-BD", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Asia/Dhaka",
  });
}

function StatusBadge({ value }) {
  const styles = {
    open: "bg-blue-50 text-blue-700",
    completed: "bg-green-50 text-green-700",
    cancelled: "bg-red-50 text-red-700",
    unpaid: "bg-red-50 text-red-700",
    partially_paid: "bg-amber-50 text-amber-700",
    paid: "bg-green-50 text-green-700",
  };

  return (
    <span
      className={`rounded-full px-3 py-1 text-xs font-semibold ${
        styles[value] || "bg-gray-100 text-gray-700"
      }`}
    >
      {(value || "unknown").replaceAll("_", " ")}
    </span>
  );
}

export default function RestaurantOrderDetails({ order }) {
  const router = useRouter();

  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState("cash");
  const [reference, setReference] = useState("");
  const [note, setNote] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const directPayments = order.payments || [];
  const checkoutAllocations = order.checkoutPaymentAllocations || [];

  const directPaid = directPayments.reduce(
    (sum, payment) => sum + Number(payment.amount || 0),
    0
  );

  const checkoutPaid = checkoutAllocations.reduce(
    (sum, allocation) => sum + Number(allocation.amount || 0),
    0
  );

  const totalPaid = directPaid + checkoutPaid;
  const outstanding = Math.max(0, Number(order.total || 0) - totalPaid);

  const totalQuantity = (order.items || []).reduce(
    (sum, item) => sum + Number(item.quantity || 0),
    0
  );

  const canRecordDirectPayment =
    order.paymentMode === "pay_now" &&
    order.orderStatus !== "cancelled" &&
    outstanding > 0;

  async function handlePaymentSubmit(event) {
    event.preventDefault();

    setError("");
    setSuccess("");

    const paymentAmount = Number(amount);

    if (!Number.isFinite(paymentAmount) || paymentAmount <= 0) {
      setError("Please enter a valid payment amount.");
      return;
    }

    if (paymentAmount > outstanding) {
      setError(
        `The maximum payable amount is ${formatMoney(outstanding)}.`
      );
      return;
    }

    try {
      setLoading(true);

      const response = await fetch(
        `/api/admin/restaurant-orders/${order._id}/payments`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            amount: paymentAmount,
            method,
            reference,
            note,
          }),
        }
      );

      const data = await response.json();

      if (!response.ok || !data.success) {
        throw new Error(
          data.message || "Failed to record payment."
        );
      }

      setSuccess(data.message || "Payment recorded successfully.");
      setAmount("");
      setMethod("cash");
      setReference("");
      setNote("");

      router.refresh();
    } catch (err) {
      setError(err.message || "Something went wrong.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto max-w-6xl space-y-6 pb-10">
      {/* Header */}
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
        <div>
          <a
            href="/admin/restaurant/orders"
            className="mb-3 inline-flex text-sm font-medium text-[#426b55] hover:underline"
          >
            ← Back to Restaurant Orders
          </a>

          <h1 className="text-2xl font-bold text-[#173729]">
            Restaurant Order Details
          </h1>

          <p className="mt-1 text-sm text-gray-500">
            Order #{order.orderNumber}
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <StatusBadge value={order.orderStatus} />
          <StatusBadge
            value={
              outstanding <= 0
                ? "paid"
                : totalPaid > 0
                  ? "partially_paid"
                  : "unpaid"
            }
          />
        </div>
      </div>

      {/* Payment summary */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <SummaryCard label="Order Total" value={formatMoney(order.total)} />
        <SummaryCard label="Direct Payments" value={formatMoney(directPaid)} />
        <SummaryCard
          label="Checkout Allocations"
          value={formatMoney(checkoutPaid)}
        />
        <SummaryCard
          label="Outstanding Balance"
          value={formatMoney(outstanding)}
        />
      </div>

      {/* Record payment */}
      {canRecordDirectPayment && (
        <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
          <h2 className="text-lg font-bold text-[#173729]">
            Record a Payment
          </h2>

          <p className="mt-1 text-sm text-gray-500">
            Enter the amount actually received from the customer.
          </p>

          <div className="mt-4 rounded-lg bg-[#f7f5ef] p-4">
            <p className="text-sm text-gray-600">
              Remaining balance
            </p>
            <p className="mt-1 text-2xl font-bold text-[#234b3b]">
              {formatMoney(outstanding)}
            </p>
          </div>

          <form onSubmit={handlePaymentSubmit} className="mt-5 space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label className="mb-2 block text-sm font-semibold text-gray-700">
                  Amount Received (৳) *
                </label>
                <input
                  type="number"
                  min="0.01"
                  max={outstanding}
                  step="0.01"
                  required
                  value={amount}
                  onChange={(event) => setAmount(event.target.value)}
                  placeholder="Enter amount"
                  className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55] focus:ring-2 focus:ring-[#426b55]/20"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-gray-700">
                  Payment Method *
                </label>
                <select
                  value={method}
                  onChange={(event) => setMethod(event.target.value)}
                  className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55]"
                >
                  <option value="cash">Cash</option>
                  <option value="bkash">bKash</option>
                  <option value="nagad">Nagad</option>
                  <option value="bank">Bank Transfer</option>
                </select>
              </div>
            </div>

            <div>
              <label className="mb-2 block text-sm font-semibold text-gray-700">
                Transaction / Reference Number
              </label>
              <input
                type="text"
                maxLength={100}
                value={reference}
                onChange={(event) => setReference(event.target.value)}
                placeholder="Optional transaction or reference number"
                className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55]"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-semibold text-gray-700">
                Payment Note
              </label>
              <textarea
                rows={3}
                maxLength={500}
                value={note}
                onChange={(event) => setNote(event.target.value)}
                placeholder="Optional payment note..."
                className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55]"
              />
            </div>

            {error && (
              <p className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                {error}
              </p>
            )}

            {success && (
              <p className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
                {success}
              </p>
            )}

            <button
              type="submit"
              disabled={loading}
              className="rounded-lg bg-[#234b3b] px-6 py-3 font-semibold text-white transition hover:bg-[#173729] disabled:cursor-not-allowed disabled:opacity-60"
            >
              {loading ? "Recording Payment..." : "Record Payment"}
            </button>
          </form>
        </section>
      )}

      {order.paymentMode === "cottage_bill" && (
        <section className="rounded-2xl border border-amber-200 bg-amber-50 p-5">
          <h2 className="font-bold text-amber-900">
            Cottage Bill Payment
          </h2>
          <p className="mt-2 text-sm text-amber-800">
            This order is added to the guest's cottage bill. Record the
            received payment against the accommodation booking during
            checkout. The amount can then be allocated to this restaurant
            order.
          </p>
        </section>
      )}

      {order.orderStatus === "cancelled" && (
        <section className="rounded-2xl border border-red-200 bg-red-50 p-5 text-sm text-red-700">
          This order is cancelled. No further payments can be recorded.
        </section>
      )}

      {outstanding <= 0 && order.orderStatus !== "cancelled" && (
        <section className="rounded-2xl border border-green-200 bg-green-50 p-5 text-sm font-medium text-green-800">
          This restaurant order is fully paid.
        </section>
      )}

      {/* Order information */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Order Information
        </h2>

        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          <InfoItem label="Order Number" value={order.orderNumber} />
          <InfoItem label="Order Type" value={order.orderType} />
          <InfoItem
            label="Payment Mode"
            value={
              order.paymentMode === "cottage_bill"
                ? "Add to Cottage Bill"
                : "Pay Immediately"
            }
          />
          <InfoItem label="Customer" value={order.guestName || "Walk-in Guest"} />
          <InfoItem label="Phone" value={order.guestPhone || "Not provided"} />
          <InfoItem label="Cottage" value={order.cottage?.name || "Walk-in"} />
          <InfoItem
            label="Booking Reference"
            value={order.booking?.bookingReference || "N/A"}
          />
          <InfoItem label="Created At" value={formatDate(order.createdAt)} />
          <InfoItem label="Total Quantity" value={totalQuantity} />
        </div>
      </section>

      {/* Food items */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Food Items
        </h2>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[550px] text-left text-sm">
            <thead className="border-b bg-gray-50 text-gray-600">
              <tr>
                <th className="px-4 py-3">Item</th>
                <th className="px-4 py-3">Price</th>
                <th className="px-4 py-3">Quantity</th>
                <th className="px-4 py-3 text-right">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {(order.items || []).map((item, index) => (
                <tr key={item._id || index}>
                  <td className="px-4 py-4 font-medium text-gray-800">
                    {item.name}
                    {item.itemType === "custom" && (
                      <span className="ml-2 text-xs text-gray-400">
                        Custom
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-4">{formatMoney(item.price)}</td>
                  <td className="px-4 py-4">{item.quantity}</td>
                  <td className="px-4 py-4 text-right font-semibold">
                    {formatMoney(item.lineTotal)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Bill breakdown */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Extra Charges & Discount
        </h2>

        <div className="space-y-3">
          <BillRow label="Food Subtotal" amount={order.subtotal} />

          {(order.extraCharges || []).map((charge, index) => (
            <BillRow
              key={charge._id || index}
              label={charge.name}
              amount={charge.amount}
            />
          ))}

          <BillRow
            label="Total Additional Charges"
            amount={order.extraChargesTotal}
          />
          <BillRow label="Discount" amount={order.discount} negative />

          <div className="border-t pt-4">
            <BillRow label="Final Order Total" amount={order.total} bold />
          </div>
        </div>

        {order.note && (
          <div className="mt-5 rounded-lg bg-gray-50 p-4">
            <p className="text-xs font-semibold uppercase text-gray-500">
              Order Note
            </p>
            <p className="mt-1 text-sm text-gray-700">{order.note}</p>
          </div>
        )}
      </section>

      {/* Payment history */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Payment History
        </h2>

        {directPayments.length === 0 && checkoutAllocations.length === 0 ? (
          <p className="rounded-lg bg-gray-50 p-5 text-sm text-gray-500">
            No payments have been recorded for this order yet.
          </p>
        ) : (
          <div className="space-y-3">
            {directPayments.map((payment, index) => (
              <div
                key={payment._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold capitalize text-gray-800">
                    {payment.method}
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(payment.paidAt)}
                  </p>
                  {payment.reference && (
                    <p className="mt-1 text-xs text-gray-500">
                      Reference: {payment.reference}
                    </p>
                  )}
                  {payment.recordedBy?.name && (
                    <p className="text-xs text-gray-500">
                      Recorded by: {payment.recordedBy.name}
                    </p>
                  )}
                  {payment.note && (
                    <p className="mt-1 text-xs text-gray-500">
                      Note: {payment.note}
                    </p>
                  )}
                </div>
                <p className="font-bold text-green-700">
                  {formatMoney(payment.amount)}
                </p>
              </div>
            ))}

            {checkoutAllocations.map((allocation, index) => (
              <div
                key={allocation._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border border-amber-200 bg-amber-50 p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold text-gray-800">
                    Cottage Checkout Payment
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(allocation.allocatedAt)}
                  </p>
                  <p className="text-xs text-gray-500">
                    Allocated from an existing booking payment
                  </p>
                </div>
                <p className="font-bold text-green-700">
                  {formatMoney(allocation.amount)}
                </p>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Order status */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="text-lg font-bold text-[#173729]">Order Status</h2>

        <p className="mt-2 text-sm text-gray-500">
          Current status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {order.orderStatus}
          </span>
        </p>

        <p className="mt-1 text-sm text-gray-500">
          Payment status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {outstanding <= 0
              ? "paid"
              : totalPaid > 0
                ? "partially paid"
                : "unpaid"}
          </span>
        </p>
      </section>
    </div>
  );
}

function SummaryCard({ label, value }) {
  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
      <p className="text-sm text-gray-500">{label}</p>
      <p className="mt-2 text-2xl font-bold text-[#234b3b]">{value}</p>
    </div>
  );
}

function InfoItem({ label, value }) {
  return (
    <div>
      <p className="text-xs font-medium uppercase tracking-wide text-gray-400">
        {label}
      </p>
      <p className="mt-1 break-words text-sm font-semibold text-gray-800">
        {value || "N/A"}
      </p>
    </div>
  );
}

function BillRow({ label, amount, negative = false, bold = false }) {
  return (
    <div
      className={`flex items-center justify-between gap-4 ${
        bold
          ? "text-lg font-bold text-[#173729]"
          : "text-sm text-gray-600"
      }`}
    >
      <span>{label}</span>
      <span className={negative ? "text-red-600" : ""}>
        {negative && Number(amount) > 0 ? "-" : ""}
        {formatMoney(amount)}
      </span>
    </div>
  );
}

import { NextResponse } from "next/server";
import mongoose from "mongoose";

import { auth } from "@/auth";
import connectDB from "@/lib/mongodb";
import RestaurantOrder from "@/models/RestaurantOrder";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const roundMoney = (value) =>
  Math.round((Number(value) + Number.EPSILON) * 100) / 100;

async function verifyAdmin() {
  const session = await auth();

  if (session?.user?.role !== "admin") {
    return null;
  }

  return session;
}

export async function POST(request, { params }) {
  let session;

  try {
    session = await verifyAdmin();

    if (!session) {
      return NextResponse.json(
        { success: false, message: "Unauthorized access." },
        { status: 403 }
      );
    }

    const adminId = session.user.id || session.user._id;

    if (!adminId || !mongoose.Types.ObjectId.isValid(adminId)) {
      return NextResponse.json(
        { success: false, message: "Invalid admin account." },
        { status: 400 }
      );
    }

    const { id } = await params;

    if (!mongoose.Types.ObjectId.isValid(id)) {
      return NextResponse.json(
        { success: false, message: "Invalid restaurant order ID." },
        { status: 400 }
      );
    }

    const body = await request.json();

    const amount = Number(body.amount);
    const method = body.method;

    const reference =
      typeof body.reference === "string"
        ? body.reference.trim()
        : "";

    const note =
      typeof body.note === "string"
        ? body.note.trim()
        : "";

    // Validate payment amount.
    if (
      !Number.isFinite(amount) ||
      amount <= 0 ||
      roundMoney(amount) !== amount
    ) {
      return NextResponse.json(
        { success: false, message: "Enter a valid payment amount." },
        { status: 400 }
      );
    }

    // Validate payment method.
    const allowedMethods = ["cash", "bkash", "nagad", "bank"];

    if (!allowedMethods.includes(method)) {
      return NextResponse.json(
        { success: false, message: "Invalid payment method." },
        { status: 400 }
      );
    }

    if (reference.length > 100 || note.length > 500) {
      return NextResponse.json(
        { success: false, message: "Reference or note is too long." },
        { status: 400 }
      );
    }

    await connectDB();

    const dbSession = await mongoose.startSession();

    let result = null;

    try {
      await dbSession.withTransaction(async () => {
        const order = await RestaurantOrder.findById(id).session(
          dbSession
        );

        if (!order) {
          result = {
            status: 404,
            body: {
              success: false,
              message: "Restaurant order not found.",
            },
          };
          return;
        }

        if (order.orderStatus === "cancelled") {
          result = {
            status: 400,
            body: {
              success: false,
              message: "Payments cannot be added to a cancelled order.",
            },
          };
          return;
        }

        // Calculate payments already received directly.
        const directPaid = roundMoney(
          order.payments.reduce(
            (sum, payment) => sum + Number(payment.amount || 0),
            0
          )
        );

        // These are existing booking payments allocated to this order.
        const checkoutPaid = roundMoney(
          order.checkoutPaymentAllocations.reduce(
            (sum, allocation) =>
              sum + Number(allocation.amount || 0),
            0
          )
        );

        const totalPaid = roundMoney(directPaid + checkoutPaid);
        const outstanding = roundMoney(
          Number(order.total) - totalPaid
        );

        if (outstanding <= 0) {
          result = {
            status: 400,
            body: {
              success: false,
              message: "This restaurant order is already fully paid.",
            },
          };
          return;
        }

        if (amount > outstanding) {
          result = {
            status: 400,
            body: {
              success: false,
              message: `Payment exceeds the outstanding balance of ৳${outstanding.toLocaleString("en-BD")}.`,
              outstanding,
            },
          };
          return;
        }

        // Record the actual payment received by the resort.
        order.payments.push({
          amount: roundMoney(amount),
          method,
          reference,
          note,
          paidAt: new Date(),
          recordedBy: adminId,
        });

        const newTotalPaid = roundMoney(totalPaid + amount);

        if (newTotalPaid >= Number(order.total)) {
          order.paymentStatus = "paid";
        } else if (newTotalPaid > 0) {
          order.paymentStatus = "partially_paid";
        } else {
          order.paymentStatus = "unpaid";
        }

        await order.save({ session: dbSession });

        result = {
          status: 200,
          body: {
            success: true,
            message: "Restaurant payment recorded successfully.",
            payment: order.payments[order.payments.length - 1],
            paymentSummary: {
              orderTotal: order.total,
              directPaid: roundMoney(directPaid + amount),
              checkoutPaid,
              totalPaid: newTotalPaid,
              outstanding: roundMoney(
                Number(order.total) - newTotalPaid
              ),
              paymentStatus: order.paymentStatus,
            },
          },
        };
      });
    } finally {
      await dbSession.endSession();
    }

    return NextResponse.json(result.body, {
      status: result.status,
    });
  } catch (error) {
    console.error("Restaurant payment POST error:", error);

    return NextResponse.json(
      {
        success: false,
        message: "Failed to record restaurant payment.",
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import mongoose from "mongoose";

import { auth } from "@/auth";
import connectDB from "@/lib/mongodb";
import RestaurantOrder from "@/models/RestaurantOrder";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const roundMoney = (value) =>
  Math.round((Number(value) + Number.EPSILON) * 100) / 100;

async function verifyAdmin() {
  const session = await auth();

  if (session?.user?.role !== "admin") {
    return null;
  }

  return session;
}

export async function POST(request, { params }) {
  try {
    // 1. Verify administrator.
    const session = await verifyAdmin();

    if (!session) {
      return NextResponse.json(
        { success: false, message: "Unauthorized access." },
        { status: 403 }
      );
    }

    const adminId = session.user.id || session.user._id;

    if (!adminId || !mongoose.Types.ObjectId.isValid(adminId)) {
      return NextResponse.json(
        { success: false, message: "Invalid admin account." },
        { status: 400 }
      );
    }

    // 2. Validate order ID.
    const { id } = await params;

    if (!mongoose.Types.ObjectId.isValid(id)) {
      return NextResponse.json(
        { success: false, message: "Invalid restaurant order ID." },
        { status: 400 }
      );
    }

    // 3. Read and validate request body.
    let body;

    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { success: false, message: "Invalid request data." },
        { status: 400 }
      );
    }

    if (!body || typeof body !== "object" || Array.isArray(body)) {
      return NextResponse.json(
        { success: false, message: "Invalid request data." },
        { status: 400 }
      );
    }

    const amount = Number(body.amount);
    const method = body.method;

    const reference =
      typeof body.reference === "string"
        ? body.reference.trim()
        : "";

    const note =
      typeof body.note === "string"
        ? body.note.trim()
        : "";

    // 4. Validate payment amount.
    if (
      !Number.isFinite(amount) ||
      amount <= 0 ||
      roundMoney(amount) !== amount
    ) {
      return NextResponse.json(
        { success: false, message: "Enter a valid payment amount." },
        { status: 400 }
      );
    }

    // 5. Validate payment method.
    const allowedMethods = ["cash", "bkash", "nagad", "bank"];

    if (!allowedMethods.includes(method)) {
      return NextResponse.json(
        { success: false, message: "Invalid payment method." },
        { status: 400 }
      );
    }

    // 6. Validate reference and note.
    if (reference.length > 100 || note.length > 500) {
      return NextResponse.json(
        {
          success: false,
          message: "Reference or note is too long.",
        },
        { status: 400 }
      );
    }

    await connectDB();

    // 7. Start MongoDB transaction.
    const dbSession = await mongoose.startSession();

    let result = null;

    try {
      await dbSession.withTransaction(async () => {
        const order = await RestaurantOrder.findById(id).session(
          dbSession
        );

        // 8. Check order existence.
        if (!order) {
          result = {
            status: 404,
            body: {
              success: false,
              message: "Restaurant order not found.",
            },
          };
          return;
        }

        // 9. Cancelled orders cannot receive payments.
        if (order.orderStatus === "cancelled") {
          result = {
            status: 400,
            body: {
              success: false,
              message:
                "Payments cannot be added to a cancelled order.",
            },
          };
          return;
        }

        // 10. Cottage Bill payments must be recorded against
        // the accommodation booking, not directly against this order.
        if (order.paymentMode === "cottage_bill") {
          result = {
            status: 400,
            body: {
              success: false,
              message:
                "This order belongs to the cottage bill. Record payment through the booking checkout instead.",
            },
          };
          return;
        }

        // 11. Calculate existing direct payments.
        const directPaid = roundMoney(
          (order.payments || []).reduce(
            (sum, payment) =>
              sum + Number(payment.amount || 0),
            0
          )
        );

        // 12. Calculate existing checkout allocations.
        // These reference existing booking payments.
        // They are NOT new payments.
        const checkoutPaid = roundMoney(
          (order.checkoutPaymentAllocations || []).reduce(
            (sum, allocation) =>
              sum + Number(allocation.amount || 0),
            0
          )
        );

        const totalPaid = roundMoney(directPaid + checkoutPaid);

        const orderTotal = roundMoney(Number(order.total || 0));

        const outstanding = roundMoney(orderTotal - totalPaid);

        // 13. Prevent payment if already fully paid.
        if (outstanding <= 0) {
          result = {
            status: 400,
            body: {
              success: false,
              message:
                "This restaurant order is already fully paid.",
            },
          };
          return;
        }

        // 14. Prevent overpayment.
        if (amount > outstanding) {
          result = {
            status: 400,
            body: {
              success: false,
              message: `Payment exceeds the outstanding balance of ৳${outstanding.toLocaleString("en-BD")}.`,
              outstanding,
            },
          };
          return;
        }

        // 15. Record actual payment received.
        order.payments.push({
          amount: roundMoney(amount),
          method,
          reference,
          note,
          paidAt: new Date(),
          recordedBy: adminId,
        });

        // 16. Update payment status.
        const newTotalPaid = roundMoney(totalPaid + amount);

        if (newTotalPaid >= orderTotal) {
          order.paymentStatus = "paid";
        } else if (newTotalPaid > 0) {
          order.paymentStatus = "partially_paid";
        } else {
          order.paymentStatus = "unpaid";
        }

        await order.save({ session: dbSession });

        // 17. Prepare response.
        const savedPayment =
          order.payments[order.payments.length - 1];

        result = {
          status: 200,
          body: {
            success: true,
            message: "Restaurant payment recorded successfully.",
            payment: {
              amount: savedPayment.amount,
              method: savedPayment.method,
              reference: savedPayment.reference,
              note: savedPayment.note,
              paidAt: savedPayment.paidAt,
              recordedBy: savedPayment.recordedBy,
            },
            paymentSummary: {
              orderTotal,
              directPaid: roundMoney(directPaid + amount),
              checkoutPaid,
              totalPaid: newTotalPaid,
              outstanding: roundMoney(orderTotal - newTotalPaid),
              paymentStatus: order.paymentStatus,
            },
          },
        };
      });
    } finally {
      await dbSession.endSession();
    }

    if (!result) {
      return NextResponse.json(
        {
          success: false,
          message: "Unable to process payment.",
        },
        { status: 500 }
      );
    }

    return NextResponse.json(result.body, {
      status: result.status,
    });
  } catch (error) {
    console.error("Restaurant payment POST error:", error);

    return NextResponse.json(
      {
        success: false,
        message: "Failed to record restaurant payment.",
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import mongoose from "mongoose";

import { auth } from "@/auth";
import connectDB from "@/lib/mongodb";
import RestaurantOrder from "@/models/RestaurantOrder";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

async function verifyAdmin() {
  const session = await auth();

  if (session?.user?.role !== "admin") {
    return null;
  }

  return session;
}

export async function POST(request, { params }) {
  try {
    const session = await verifyAdmin();

    if (!session) {
      return NextResponse.json(
        { success: false, message: "Unauthorized access." },
        { status: 403 }
      );
    }

    const adminId = session.user.id || session.user._id;

    if (!adminId || !mongoose.Types.ObjectId.isValid(adminId)) {
      return NextResponse.json(
        { success: false, message: "Invalid admin account." },
        { status: 400 }
      );
    }

    const { id } = await params;

    if (!mongoose.Types.ObjectId.isValid(id)) {
      return NextResponse.json(
        { success: false, message: "Invalid restaurant order ID." },
        { status: 400 }
      );
    }

    let body;

    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { success: false, message: "Invalid request data." },
        { status: 400 }
      );
    }

    if (!body || typeof body !== "object" || Array.isArray(body)) {
      return NextResponse.json(
        { success: false, message: "Invalid request data." },
        { status: 400 }
      );
    }

    const method = body.method;

    const reference =
      typeof body.reference === "string"
        ? body.reference.trim()
        : "";

    const note =
      typeof body.note === "string"
        ? body.note.trim()
        : "";

    const allowedMethods = ["cash", "bkash", "nagad", "bank"];

    if (!allowedMethods.includes(method)) {
      return NextResponse.json(
        { success: false, message: "Invalid payment method." },
        { status: 400 }
      );
    }

    if (reference.length > 100 || note.length > 500) {
      return NextResponse.json(
        { success: false, message: "Reference or note is too long." },
        { status: 400 }
      );
    }

    await connectDB();

    const order = await RestaurantOrder.findById(id);

    if (!order) {
      return NextResponse.json(
        { success: false, message: "Restaurant order not found." },
        { status: 404 }
      );
    }

    if (order.orderStatus === "cancelled") {
      return NextResponse.json(
        {
          success: false,
          message: "Payments cannot be added to a cancelled order.",
        },
        { status: 400 }
      );
    }

    if (order.paymentMode === "cottage_bill") {
      return NextResponse.json(
        {
          success: false,
          message:
            "This order belongs to the cottage bill. Record payment through the booking checkout instead.",
        },
        { status: 400 }
      );
    }

    if (order.paymentMode !== "pay_now") {
      return NextResponse.json(
        { success: false, message: "Invalid restaurant payment mode." },
        { status: 400 }
      );
    }

    // A restaurant order must be paid in one full transaction.
    if (order.paymentStatus === "paid" || order.payments?.length > 0) {
      return NextResponse.json(
        {
          success: false,
          message: "A payment has already been recorded for this order.",
        },
        { status: 400 }
      );
    }

    const amount = Number(order.total);

    if (!Number.isFinite(amount) || amount <= 0) {
      return NextResponse.json(
        { success: false, message: "Invalid restaurant order total." },
        { status: 400 }
      );
    }

    order.payments = [
      {
        amount,
        method,
        reference,
        note,
        paidAt: new Date(),
        recordedBy: adminId,
      },
    ];

    order.paymentStatus = "paid";

    await order.save();

    return NextResponse.json({
      success: true,
      message: "Full restaurant payment recorded successfully.",
      paymentSummary: {
        orderTotal: amount,
        totalPaid: amount,
        outstanding: 0,
        paymentStatus: "paid",
      },
    });
  } catch (error) {
    console.error("Restaurant payment POST error:", error);

    return NextResponse.json(
      {
        success: false,
        message: "Failed to record restaurant payment.",
      },
      { status: 500 }
    );
  }
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

function formatMoney(amount) {
  return `৳${Number(amount || 0).toLocaleString("en-BD")}`;
}

function formatDate(date) {
  if (!date) return "Not available";

  return new Date(date).toLocaleString("en-BD", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Asia/Dhaka",
  });
}

function StatusBadge({ value }) {
  const styles = {
    open: "bg-blue-50 text-blue-700",
    completed: "bg-green-50 text-green-700",
    cancelled: "bg-red-50 text-red-700",
    unpaid: "bg-red-50 text-red-700",
    partially_paid: "bg-amber-50 text-amber-700",
    paid: "bg-green-50 text-green-700",
  };

  return (
    <span
      className={`rounded-full px-3 py-1 text-xs font-semibold ${styles[value] || "bg-gray-100 text-gray-700"
        }`}
    >
      {(value || "unknown").replaceAll("_", " ")}
    </span>
  );
}

export default function RestaurantOrderDetails({ order }) {
  const router = useRouter();

  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState("cash");
  const [reference, setReference] = useState("");
  const [note, setNote] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const directPayments = order.payments || [];
  const checkoutAllocations = order.checkoutPaymentAllocations || [];

  const directPaid = directPayments.reduce(
    (sum, payment) => sum + Number(payment.amount || 0),
    0
  );

  const checkoutPaid = checkoutAllocations.reduce(
    (sum, allocation) => sum + Number(allocation.amount || 0),
    0
  );

  const totalPaid = directPaid + checkoutPaid;
  const outstanding = Math.max(0, Number(order.total || 0) - totalPaid);

  const totalQuantity = (order.items || []).reduce(
    (sum, item) => sum + Number(item.quantity || 0),
    0
  );

  const canRecordDirectPayment =
    order.paymentMode === "pay_now" &&
    order.orderStatus !== "cancelled" &&
    outstanding > 0;

  async function handlePaymentSubmit(event) {
    event.preventDefault();

    setError("");
    setSuccess("");

    const paymentAmount = Number(amount);

    if (!Number.isFinite(paymentAmount) || paymentAmount <= 0) {
      setError("Please enter a valid payment amount.");
      return;
    }

    if (paymentAmount > outstanding) {
      setError(
        `The maximum payable amount is ${formatMoney(outstanding)}.`
      );
      return;
    }

    try {
      setLoading(true);

      const response = await fetch(
        `/api/admin/restaurant-orders/${order._id}/payments`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            amount: paymentAmount,
            method,
            reference,
            note,
          }),
        }
      );

      const data = await response.json();

      if (!response.ok || !data.success) {
        throw new Error(
          data.message || "Failed to record payment."
        );
      }

      setSuccess(data.message || "Payment recorded successfully.");
      setAmount("");
      setMethod("cash");
      setReference("");
      setNote("");

      router.refresh();
    } catch (err) {
      setError(err.message || "Something went wrong.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto max-w-6xl space-y-6 pb-10">
      {/* Header */}
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
        <div>
          <a
            href="/admin/restaurant/orders"
            className="mb-3 inline-flex text-sm font-medium text-[#426b55] hover:underline"
          >
            ← Back to Restaurant Orders
          </a>

          <h1 className="text-2xl font-bold text-[#173729]">
            Restaurant Order Details
          </h1>

          <p className="mt-1 text-sm text-gray-500">
            Order #{order.orderNumber}
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <StatusBadge value={order.orderStatus} />
          <StatusBadge
            value={
              outstanding <= 0
                ? "paid"
                : totalPaid > 0
                  ? "partially_paid"
                  : "unpaid"
            }
          />
        </div>
      </div>

      {/* Payment summary */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <SummaryCard label="Order Total" value={formatMoney(order.total)} />
        <SummaryCard label="Direct Payments" value={formatMoney(directPaid)} />
        <SummaryCard
          label="Checkout Allocations"
          value={formatMoney(checkoutPaid)}
        />
        <SummaryCard
          label="Outstanding Balance"
          value={formatMoney(outstanding)}
        />
      </div>

      {/* Record payment */}
      {canRecordDirectPayment && (
        <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
          <h2 className="text-lg font-bold text-[#173729]">
            Record a Payment
          </h2>

          <p className="mt-1 text-sm text-gray-500">
            Enter the amount actually received from the customer.
          </p>

          <div className="mt-4 rounded-lg bg-[#f7f5ef] p-4">
            <p className="text-sm text-gray-600">
              Remaining balance
            </p>
            <p className="mt-1 text-2xl font-bold text-[#234b3b]">
              {formatMoney(outstanding)}
            </p>
          </div>

          <form onSubmit={handlePaymentSubmit} className="mt-5 space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label className="mb-2 block text-sm font-semibold text-gray-700">
                  Amount Received (৳) *
                </label>
                <input
                  type="number"
                  min="0.01"
                  max={outstanding}
                  step="0.01"
                  required
                  value={amount}
                  onChange={(event) => setAmount(event.target.value)}
                  placeholder="Enter amount"
                  className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55] focus:ring-2 focus:ring-[#426b55]/20"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-gray-700">
                  Payment Method *
                </label>
                <select
                  value={method}
                  onChange={(event) => setMethod(event.target.value)}
                  className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55]"
                >
                  <option value="cash">Cash</option>
                  <option value="bkash">bKash</option>
                  <option value="nagad">Nagad</option>
                  <option value="bank">Bank Transfer</option>
                </select>
              </div>
            </div>

            <div>
              <label className="mb-2 block text-sm font-semibold text-gray-700">
                Transaction / Reference Number
              </label>
              <input
                type="text"
                maxLength={100}
                value={reference}
                onChange={(event) => setReference(event.target.value)}
                placeholder="Optional transaction or reference number"
                className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55]"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-semibold text-gray-700">
                Payment Note
              </label>
              <textarea
                rows={3}
                maxLength={500}
                value={note}
                onChange={(event) => setNote(event.target.value)}
                placeholder="Optional payment note..."
                className="w-full rounded-lg border border-gray-300 px-4 py-3 outline-none focus:border-[#426b55]"
              />
            </div>

            {error && (
              <p className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                {error}
              </p>
            )}

            {success && (
              <p className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
                {success}
              </p>
            )}

            <button
              type="submit"
              disabled={loading}
              className="rounded-lg bg-[#234b3b] px-6 py-3 font-semibold text-white transition hover:bg-[#173729] disabled:cursor-not-allowed disabled:opacity-60"
            >
              {loading ? "Recording Payment..." : "Record Payment"}
            </button>
          </form>
        </section>
      )}

      {order.paymentMode === "cottage_bill" && (
        <section className="rounded-2xl border border-amber-200 bg-amber-50 p-5">
          <h2 className="font-bold text-amber-900">
            Cottage Bill Payment
          </h2>
          <p className="mt-2 text-sm text-amber-800">
            This order is added to the guest's cottage bill. Record the
            received payment against the accommodation booking during
            checkout. The amount can then be allocated to this restaurant
            order.
          </p>
        </section>
      )}

      {order.orderStatus === "cancelled" && (
        <section className="rounded-2xl border border-red-200 bg-red-50 p-5 text-sm text-red-700">
          This order is cancelled. No further payments can be recorded.
        </section>
      )}

      {outstanding <= 0 && order.orderStatus !== "cancelled" && (
        <section className="rounded-2xl border border-green-200 bg-green-50 p-5 text-sm font-medium text-green-800">
          This restaurant order is fully paid.
        </section>
      )}

      {/* Order information */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Order Information
        </h2>

        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          <InfoItem label="Order Number" value={order.orderNumber} />
          <InfoItem label="Order Type" value={order.orderType} />
          <InfoItem
            label="Payment Mode"
            value={
              order.paymentMode === "cottage_bill"
                ? "Add to Cottage Bill"
                : "Pay Immediately"
            }
          />
          <InfoItem label="Customer" value={order.guestName || "Walk-in Guest"} />
          <InfoItem label="Phone" value={order.guestPhone || "Not provided"} />
          <InfoItem label="Cottage" value={order.cottage?.name || "Walk-in"} />
          <InfoItem
            label="Booking Reference"
            value={order.booking?.bookingReference || "N/A"}
          />
          <InfoItem label="Created At" value={formatDate(order.createdAt)} />
          <InfoItem label="Total Quantity" value={totalQuantity} />
        </div>
      </section>

      {/* Food items */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Food Items
        </h2>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[550px] text-left text-sm">
            <thead className="border-b bg-gray-50 text-gray-600">
              <tr>
                <th className="px-4 py-3">Item</th>
                <th className="px-4 py-3">Price</th>
                <th className="px-4 py-3">Quantity</th>
                <th className="px-4 py-3 text-right">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {(order.items || []).map((item, index) => (
                <tr key={item._id || index}>
                  <td className="px-4 py-4 font-medium text-gray-800">
                    {item.name}
                    {item.itemType === "custom" && (
                      <span className="ml-2 text-xs text-gray-400">
                        Custom
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-4">{formatMoney(item.price)}</td>
                  <td className="px-4 py-4">{item.quantity}</td>
                  <td className="px-4 py-4 text-right font-semibold">
                    {formatMoney(item.lineTotal)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Bill breakdown */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Extra Charges & Discount
        </h2>

        <div className="space-y-3">
          <BillRow label="Food Subtotal" amount={order.subtotal} />

          {(order.extraCharges || []).map((charge, index) => (
            <BillRow
              key={charge._id || index}
              label={charge.name}
              amount={charge.amount}
            />
          ))}

          <BillRow
            label="Total Additional Charges"
            amount={order.extraChargesTotal}
          />
          <BillRow label="Discount" amount={order.discount} negative />

          <div className="border-t pt-4">
            <BillRow label="Final Order Total" amount={order.total} bold />
          </div>
        </div>

        {order.note && (
          <div className="mt-5 rounded-lg bg-gray-50 p-4">
            <p className="text-xs font-semibold uppercase text-gray-500">
              Order Note
            </p>
            <p className="mt-1 text-sm text-gray-700">{order.note}</p>
          </div>
        )}
      </section>

      {/* Payment history */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="mb-5 text-lg font-bold text-[#173729]">
          Payment History
        </h2>

        {directPayments.length === 0 && checkoutAllocations.length === 0 ? (
          <p className="rounded-lg bg-gray-50 p-5 text-sm text-gray-500">
            No payments have been recorded for this order yet.
          </p>
        ) : (
          <div className="space-y-3">
            {directPayments.map((payment, index) => (
              <div
                key={payment._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold capitalize text-gray-800">
                    {payment.method}
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(payment.paidAt)}
                  </p>
                  {payment.reference && (
                    <p className="mt-1 text-xs text-gray-500">
                      Reference: {payment.reference}
                    </p>
                  )}
                  {payment.recordedBy?.name && (
                    <p className="text-xs text-gray-500">
                      Recorded by: {payment.recordedBy.name}
                    </p>
                  )}
                  {payment.note && (
                    <p className="mt-1 text-xs text-gray-500">
                      Note: {payment.note}
                    </p>
                  )}
                </div>
                <p className="font-bold text-green-700">
                  {formatMoney(payment.amount)}
                </p>
              </div>
            ))}

            {checkoutAllocations.map((allocation, index) => (
              <div
                key={allocation._id || index}
                className="flex flex-col justify-between gap-2 rounded-lg border border-amber-200 bg-amber-50 p-4 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="font-semibold text-gray-800">
                    Cottage Checkout Payment
                  </p>
                  <p className="text-xs text-gray-500">
                    {formatDate(allocation.allocatedAt)}
                  </p>
                  <p className="text-xs text-gray-500">
                    Allocated from an existing booking payment
                  </p>
                </div>
                <p className="font-bold text-green-700">
                  {formatMoney(allocation.amount)}
                </p>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Order status */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
        <h2 className="text-lg font-bold text-[#173729]">Order Status</h2>

        <p className="mt-2 text-sm text-gray-500">
          Current status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {order.orderStatus}
          </span>
        </p>

        <p className="mt-1 text-sm text-gray-500">
          Payment status:{" "}
          <span className="font-semibold capitalize text-gray-800">
            {outstanding <= 0
              ? "paid"
              : totalPaid > 0
                ? "partially paid"
                : "unpaid"}
          </span>
        </p>
      </section>
    </div>
  );
}

function SummaryCard({ label, value }) {
  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
      <p className="text-sm text-gray-500">{label}</p>
      <p className="mt-2 text-2xl font-bold text-[#234b3b]">{value}</p>
    </div>
  );
}

function InfoItem({ label, value }) {
  return (
    <div>
      <p className="text-xs font-medium uppercase tracking-wide text-gray-400">
        {label}
      </p>
      <p className="mt-1 break-words text-sm font-semibold text-gray-800">
        {value || "N/A"}
      </p>
    </div>
  );
}

function BillRow({ label, amount, negative = false, bold = false }) {
  return (
    <div
      className={`flex items-center justify-between gap-4 ${bold
          ? "text-lg font-bold text-[#173729]"
          : "text-sm text-gray-600"
        }`}
    >
      <span>{label}</span>
      <span className={negative ? "text-red-600" : ""}>
        {negative && Number(amount) > 0 ? "-" : ""}
        {formatMoney(amount)}
      </span>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import {
  ArrowLeft,
  CalendarDays,
  CheckCircle2,
  ClipboardList,
  CreditCard,
  FileText,
  MapPin,
  Phone,
  Receipt,
  ShoppingBag,
  UserRound,
  Wallet,
  Clock3,
} from "lucide-react";

function formatMoney(amount) {
  return `৳${Number(amount || 0).toLocaleString("en-BD")}`;
}

function formatDate(date) {
  if (!date) return "Not available";

  return new Date(date).toLocaleString("en-BD", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Asia/Dhaka",
  });
}

function StatusBadge({ value }) {
  const isPaid = value === "paid";
  const isCancelled = value === "cancelled";
  const styles = isPaid
    ? "bg-emerald-50 text-emerald-700 ring-emerald-600/20"
    : isCancelled
      ? "bg-red-50 text-red-700 ring-red-600/20"
      : "bg-amber-50 text-amber-700 ring-amber-600/20";

  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-semibold capitalize ring-1 ring-inset ${styles}`}>
      {isPaid ? <CheckCircle2 size={13} /> : null}
      {(value || "unknown").replaceAll("_", " ")}
    </span>
  );
}

export default function RestaurantOrderDetails({ order }) {
  const router = useRouter();

  const [method, setMethod] = useState("cash");
  const [reference, setReference] = useState("");
  const [note, setNote] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const directPayments = order.payments || [];
  const checkoutAllocations = order.checkoutPaymentAllocations || [];

  const directPaid = directPayments.reduce(
    (sum, payment) => sum + Number(payment.amount || 0),
    0
  );

  const checkoutPaid = checkoutAllocations.reduce(
    (sum, allocation) => sum + Number(allocation.amount || 0),
    0
  );

  const totalPaid = directPaid + checkoutPaid;
  const orderTotal = Number(order.total || 0);
  const isPaid = order.paymentStatus === "paid" || totalPaid >= orderTotal;
  const isCancelled = order.orderStatus === "cancelled";
  const isCottageBill = order.paymentMode === "cottage_bill";

  const canRecordPayment =
    !isCottageBill && !isCancelled && !isPaid && directPayments.length === 0;

  const totalQuantity = (order.items || []).reduce(
    (sum, item) => sum + Number(item.quantity || 0),
    0
  );

  async function handlePaymentSubmit(event) {
    event.preventDefault();
    setError("");
    setSuccess("");

    try {
      setLoading(true);

      const response = await fetch(
        `/api/admin/restaurant-orders/${order._id}/payments`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            method,
            reference,
            note,
          }),
        }
      );

      const data = await response.json();

      if (!response.ok || !data.success) {
        throw new Error(data.message || "Failed to record payment.");
      }

      setSuccess(data.message || "Full payment recorded successfully.");
      setReference("");
      setNote("");
      router.refresh();
    } catch (err) {
      setError(err.message || "Something went wrong.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto max-w-7xl space-y-6 pb-12">
      {/* Header */}
      <div className="flex flex-col justify-between gap-4 rounded-2xl border border-gray-200 bg-white p-5 shadow-sm sm:flex-row sm:items-center">
        <div>
          <a
            href="/admin/restaurant/orders"
            className="mb-4 inline-flex items-center gap-2 text-sm font-medium text-[#426b55] transition hover:text-[#173729]"
          >
            <ArrowLeft size={16} />
            Back to Restaurant Orders
          </a>

          <div className="flex flex-wrap items-center gap-3">
            <h1 className="text-2xl font-bold tracking-tight text-[#173729]">
              Restaurant Order
            </h1>
            <span className="rounded-lg bg-[#f7f5ef] px-3 py-1.5 font-mono text-sm font-semibold text-[#426b55]">
              {order.orderNumber}
            </span>
          </div>

          <p className="mt-2 text-sm text-gray-500">
            Review order information, bill details and payment records.
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <StatusBadge value={order.orderStatus} />
          <StatusBadge value={isPaid ? "paid" : "unpaid"} />
        </div>
      </div>

      {/* Financial overview */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <SummaryCard
          icon={Receipt}
          label="Total Order Amount"
          value={formatMoney(orderTotal)}
          description="Final bill including charges and discount"
        />
        <SummaryCard
          icon={Wallet}
          label="Payment Received"
          value={formatMoney(totalPaid)}
          description="Recorded restaurant and checkout payments"
        />
        <SummaryCard
          icon={CheckCircle2}
          label="Payment Status"
          value={isPaid ? "Paid" : "Unpaid"}
          description={isPaid ? "Payment is fully settled" : "Payment is not yet recorded"}
          success={isPaid}
        />
      </div>

      {/* Payment action */}
      {canRecordPayment && (
        <section className="overflow-hidden rounded-2xl border border-[#dce7df] bg-white shadow-sm">
          <div className="flex items-center gap-3 border-b border-gray-100 bg-[#f4f8f4] px-5 py-4">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#234b3b] text-white">
              <CreditCard size={19} />
            </div>
            <div>
              <h2 className="font-bold text-[#173729]">Record Full Payment</h2>
              <p className="text-xs text-gray-500">
                Record the complete restaurant bill in one transaction.
              </p>
            </div>
          </div>

          <form onSubmit={handlePaymentSubmit} className="space-y-5 p-5">
            <div className="flex flex-col justify-between gap-2 rounded-xl border border-[#e3eadf] bg-[#f7f8f4] p-4 sm:flex-row sm:items-center">
              <div>
                <p className="text-sm font-medium text-gray-600">Full amount to collect</p>
                <p className="mt-1 text-xs text-gray-400">
                  This amount is calculated from the saved order.
                </p>
              </div>
              <p className="text-3xl font-bold tracking-tight text-[#234b3b]">
                {formatMoney(orderTotal)}
              </p>
            </div>

            <div className="grid gap-5 sm:grid-cols-2">
              <div>
                <label className="mb-2 block text-sm font-semibold text-gray-700">
                  Payment Method <span className="text-red-500">*</span>
                </label>
                <select
                  required
                  value={method}
                  onChange={(event) => setMethod(event.target.value)}
                  className="w-full rounded-xl border border-gray-300 bg-white px-4 py-3 text-sm outline-none transition focus:border-[#426b55] focus:ring-2 focus:ring-[#426b55]/15"
                >
                  <option value="cash">Cash</option>
                  <option value="bkash">bKash</option>
                  <option value="nagad">Nagad</option>
                  <option value="bank">Bank Transfer</option>
                </select>
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-gray-700">
                  Transaction / Reference Number
                </label>
                <input
                  type="text"
                  maxLength={100}
                  value={reference}
                  onChange={(event) => setReference(event.target.value)}
                  placeholder="Optional reference number"
                  className="w-full rounded-xl border border-gray-300 px-4 py-3 text-sm outline-none transition focus:border-[#426b55] focus:ring-2 focus:ring-[#426b55]/15"
                />
              </div>
            </div>

            <div>
              <label className="mb-2 block text-sm font-semibold text-gray-700">
                Payment Note
              </label>
              <textarea
                rows={3}
                maxLength={500}
                value={note}
                onChange={(event) => setNote(event.target.value)}
                placeholder="Optional note about this payment..."
                className="w-full rounded-xl border border-gray-300 px-4 py-3 text-sm outline-none transition focus:border-[#426b55] focus:ring-2 focus:ring-[#426b55]/15"
              />
            </div>

            {error && (
              <p className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">
                {error}
              </p>
            )}

            {success && (
              <p className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">
                {success}
              </p>
            )}

            <div className="flex flex-col justify-between gap-3 border-t border-gray-100 pt-4 sm:flex-row sm:items-center">
              <p className="text-xs text-gray-500">
                Confirm that the full amount has actually been received before recording.
              </p>
              <button
                type="submit"
                disabled={loading}
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#234b3b] px-6 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-[#173729] disabled:cursor-not-allowed disabled:opacity-60"
              >
                <CheckCircle2 size={17} />
                {loading ? "Recording..." : "Confirm Full Payment"}
              </button>
            </div>
          </form>
        </section>
      )}

      {isCottageBill && (
        <section className="flex gap-4 rounded-2xl border border-amber-200 bg-amber-50 p-5">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-amber-100 text-amber-800">
            <Wallet size={21} />
          </div>
          <div>
            <h2 className="font-bold text-amber-950">Added to Cottage Bill</h2>
            <p className="mt-1 text-sm leading-6 text-amber-900/80">
              This restaurant order is included in the guest&apos;s accommodation bill.
              Collect the combined amount during checkout and record the payment
              against the booking. The existing booking payment can then be allocated
              to this restaurant order.
            </p>
          </div>
        </section>
      )}

      {isCancelled && (
        <Notice
          title="Order Cancelled"
          message="This order has been cancelled. No further payments can be recorded."
          tone="red"
        />
      )}

      {isPaid && !isCancelled && (
        <Notice
          title="Payment Completed"
          message="The full restaurant order amount has been received and recorded successfully."
          tone="green"
        />
      )}

      {/* Order information */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm sm:p-6">
        <SectionHeading
          icon={ClipboardList}
          title="Order Information"
          description="Customer and order details"
        />

        <div className="mt-6 grid gap-x-8 gap-y-6 sm:grid-cols-2 lg:grid-cols-3">
          <InfoItem icon={FileText} label="Order Number" value={order.orderNumber} />
          <InfoItem icon={ShoppingBag} label="Order Type" value={order.orderType === "walk-in" ? "Walk-in" : "Cottage Guest"} />
          <InfoItem icon={CreditCard} label="Payment Mode" value={isCottageBill ? "Add to Cottage Bill" : "Pay Immediately"} />
          <InfoItem icon={UserRound} label="Customer" value={order.guestName || "Walk-in Guest"} />
          <InfoItem icon={Phone} label="Phone" value={order.guestPhone || "Not provided"} />
          <InfoItem icon={MapPin} label="Cottage" value={order.cottage?.name || "Walk-in"} />
          <InfoItem icon={FileText} label="Booking Reference" value={order.booking?.bookingReference || "N/A"} />
          <InfoItem icon={CalendarDays} label="Created At" value={formatDate(order.createdAt)} />
          <InfoItem icon={ShoppingBag} label="Total Quantity" value={totalQuantity} />
        </div>
      </section>

      {/* Food items */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm sm:p-6">
        <SectionHeading
          icon={ShoppingBag}
          title="Food Items"
          description={`${(order.items || []).length} item types · ${totalQuantity} total quantity`}
        />

        <div className="mt-5 overflow-x-auto">
          <table className="w-full min-w-[550px] text-left text-sm">
            <thead>
              <tr className="border-y border-gray-100 bg-gray-50 text-xs uppercase tracking-wide text-gray-500">
                <th className="px-4 py-3 font-semibold">Food Item</th>
                <th className="px-4 py-3 font-semibold">Unit Price</th>
                <th className="px-4 py-3 font-semibold">Quantity</th>
                <th className="px-4 py-3 text-right font-semibold">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {(order.items || []).map((item, index) => (
                <tr key={item._id || index} className="hover:bg-gray-50/70">
                  <td className="px-4 py-4 font-semibold text-gray-800">
                    {item.name}
                    {item.itemType === "custom" && (
                      <span className="ml-2 rounded-md bg-gray-100 px-2 py-1 text-[10px] font-semibold uppercase text-gray-500">
                        Custom
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-4 text-gray-600">{formatMoney(item.price)}</td>
                  <td className="px-4 py-4 text-gray-600">{item.quantity}</td>
                  <td className="px-4 py-4 text-right font-bold text-gray-800">
                    {formatMoney(item.lineTotal)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Bill breakdown */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm sm:p-6">
        <SectionHeading
          icon={Receipt}
          title="Bill Breakdown"
          description="Complete calculation of this restaurant order"
        />

        <div className="mt-5 ml-auto max-w-xl space-y-4">
          <BillRow label="Food Subtotal" amount={order.subtotal} />

          {(order.extraCharges || []).map((charge, index) => (
            <BillRow
              key={charge._id || index}
              label={charge.name}
              amount={charge.amount}
            />
          ))}

          {Number(order.extraChargesTotal || 0) > 0 && (
            <BillRow label="Additional Charges" amount={order.extraChargesTotal} />
          )}

          {Number(order.discount || 0) > 0 && (
            <BillRow label="Discount" amount={order.discount} negative />
          )}

          <div className="border-t border-dashed border-gray-200 pt-4">
            <div className="flex items-center justify-between gap-4">
              <span className="font-bold text-[#173729]">Final Order Total</span>
              <span className="text-2xl font-bold text-[#234b3b]">
                {formatMoney(order.total)}
              </span>
            </div>
          </div>
        </div>

        {order.note && (
          <div className="mt-6 rounded-xl bg-gray-50 p-4">
            <p className="text-xs font-bold uppercase tracking-wide text-gray-500">Order Note</p>
            <p className="mt-2 text-sm leading-6 text-gray-700">{order.note}</p>
          </div>
        )}
      </section>

      {/* Payment history */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm sm:p-6">
        <SectionHeading
          icon={Wallet}
          title="Payment Records"
          description="Recorded payments associated with this order"
        />

        {directPayments.length === 0 && checkoutAllocations.length === 0 ? (
          <div className="mt-5 rounded-xl border border-dashed border-gray-200 bg-gray-50 px-5 py-8 text-center">
            <Wallet className="mx-auto text-gray-400" size={28} />
            <p className="mt-3 text-sm font-semibold text-gray-700">No payment recorded yet</p>
            <p className="mt-1 text-xs text-gray-500">
              Payment details will appear here once recorded.
            </p>
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {directPayments.map((payment, index) => (
              <PaymentRecord
                key={payment._id || index}
                title={payment.method}
                amount={payment.amount}
                date={payment.paidAt}
                reference={payment.reference}
                note={payment.note}
                recordedBy={payment.recordedBy?.name}
              />
            ))}

            {checkoutAllocations.map((allocation, index) => (
              <PaymentRecord
                key={allocation._id || index}
                title="Cottage Checkout Payment"
                amount={allocation.amount}
                date={allocation.allocatedAt}
                note="Allocated from an existing booking payment"
                highlighted
              />
            ))}
          </div>
        )}
      </section>

      {/* Status */}
      <section className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm sm:p-6">
        <SectionHeading
          icon={Clock3}
          title="Order Status"
          description="Current order and payment state"
        />
        <div className="mt-5 flex flex-wrap items-center gap-3">
          <span className="text-sm text-gray-500">Order:</span>
          <StatusBadge value={order.orderStatus} />
          <span className="ml-2 text-sm text-gray-500">Payment:</span>
          <StatusBadge value={isPaid ? "paid" : "unpaid"} />
        </div>
      </section>
    </div>
  );
}

function SummaryCard({ icon: Icon, label, value, description, success = false }) {
  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
      <div className="flex items-center justify-between gap-3">
        <p className="text-sm font-medium text-gray-500">{label}</p>
        <span className={`flex h-9 w-9 items-center justify-center rounded-xl ${success ? "bg-emerald-50 text-emerald-700" : "bg-[#f2f5f1] text-[#426b55]"}`}>
          <Icon size={18} />
        </span>
      </div>
      <p className={`mt-3 text-2xl font-bold tracking-tight ${success ? "text-emerald-700" : "text-[#234b3b]"}`}>
        {value}
      </p>
      <p className="mt-1 text-xs text-gray-400">{description}</p>
    </div>
  );
}

function SectionHeading({ icon: Icon, title, description }) {
  return (
    <div className="flex items-start gap-3">
      <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f1] text-[#426b55]">
        <Icon size={19} />
      </span>
      <div>
        <h2 className="font-bold text-[#173729]">{title}</h2>
        <p className="mt-1 text-xs text-gray-500">{description}</p>
      </div>
    </div>
  );
}

function InfoItem({ icon: Icon, label, value }) {
  return (
    <div className="flex gap-3">
      <Icon size={16} className="mt-0.5 shrink-0 text-[#78917f]" />
      <div className="min-w-0">
        <p className="text-[11px] font-semibold uppercase tracking-wide text-gray-400">{label}</p>
        <p className="mt-1 break-words text-sm font-semibold text-gray-800">{value || "N/A"}</p>
      </div>
    </div>
  );
}

function BillRow({ label, amount, negative = false }) {
  return (
    <div className="flex items-center justify-between gap-4 text-sm">
      <span className="text-gray-500">{label}</span>
      <span className={`font-semibold ${negative ? "text-red-600" : "text-gray-800"}`}>
        {negative ? "-" : ""}{formatMoney(amount)}
      </span>
    </div>
  );
}

function PaymentRecord({ title, amount, date, reference, note, recordedBy, highlighted = false }) {
  return (
    <div className={`flex flex-col justify-between gap-3 rounded-xl border p-4 sm:flex-row sm:items-center ${highlighted ? "border-amber-200 bg-amber-50/60" : "border-gray-200 bg-white"}`}>
      <div className="flex gap-3">
        <span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${highlighted ? "bg-amber-100 text-amber-800" : "bg-emerald-50 text-emerald-700"}`}>
          <Wallet size={18} />
        </span>
        <div>
          <p className="text-sm font-bold capitalize text-gray-800">{title}</p>
          <p className="mt-1 text-xs text-gray-500">{formatDate(date)}</p>
          {reference && <p className="mt-1 text-xs text-gray-500">Reference: {reference}</p>}
          {recordedBy && <p className="mt-1 text-xs text-gray-500">Recorded by: {recordedBy}</p>}
          {note && <p className="mt-1 text-xs text-gray-500">Note: {note}</p>}
        </div>
      </div>
      <p className="text-lg font-bold text-emerald-700">{formatMoney(amount)}</p>
    </div>
  );
}

function Notice({ title, message, tone }) {
  const green = tone === "green";

  return (
    <div className={`flex gap-3 rounded-2xl border p-5 ${green ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-red-200 bg-red-50 text-red-800"}`}>
      <CheckCircle2 className="mt-0.5 shrink-0" size={20} />
      <div>
        <p className="font-bold">{title}</p>
        <p className="mt-1 text-sm">{message}</p>
      </div>
    </div>
  );
}
